-- TEST-ONLY fixture derived from BD-005.2 M1 tables.
-- NOT a historical Flyway V001–V009 migration. Replace when authorized SQL is restored.

CREATE TABLE "Rol" (
    "idRol" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "nombre" VARCHAR(30) NOT NULL UNIQUE,
    "descripcion" TEXT NOT NULL
);

CREATE TABLE "Permiso" (
    "idPermiso" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "codigo" VARCHAR(100) NOT NULL UNIQUE,
    "nombre" VARCHAR(100) NOT NULL,
    "descripcion" TEXT
);

CREATE TABLE "Usuario" (
    "idUsuario" UUID PRIMARY KEY,
    "idRol" INTEGER NOT NULL REFERENCES "Rol" ("idRol"),
    "nombre" VARCHAR(150) NOT NULL,
    "correo" VARCHAR(255) NOT NULL UNIQUE,
    "passwordHash" VARCHAR(255),
    "estado" VARCHAR(20) NOT NULL DEFAULT 'Activo',
    "fechaCreacion" TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    "fechaActualizacion" TIMESTAMPTZ
);

CREATE TABLE "UsuarioPermiso" (
    "idUsuario" UUID NOT NULL REFERENCES "Usuario" ("idUsuario"),
    "idPermiso" INTEGER NOT NULL REFERENCES "Permiso" ("idPermiso"),
    "habilitado" BOOLEAN NOT NULL DEFAULT TRUE,
    "idAdministradorAsignador" UUID,
    "fechaAsignacion" TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    PRIMARY KEY ("idUsuario", "idPermiso")
);
